'use strict';
function initProHelp(){
 if(isViewer||isProjector)return;
 const manual='help/Teacher-Studio-Manual.pdf';
 const links=`<p class="row" style="margin:14px 0 20px"><a href="${manual}" target="_blank" rel="noopener" class="pro-manual-link">Open PDF manual ↗</a><a href="${manual}" download="Mr-Drews-Uke-Strum-Pro-Manual.pdf" class="pro-manual-link">Download manual</a></p>`;
 const style=document.createElement('style');style.textContent='.pro-manual-link{display:inline-block;padding:11px 16px;border-radius:10px;background:#14786f;color:#fff;text-decoration:none;font-weight:700}.pro-help-list{padding-left:23px;line-height:1.7}.pro-help-list li{margin-bottom:12px}.pro-help-list b{color:#155e67}';document.head.appendChild(style);
 $('helpBtn').onclick=()=>{
  $('optionsModal').close();
  showInfo('Teacher Studio Pro - Help',`<p class="modal-note">Create a song, teach it, send a practice sheet home, or make a composition video. The illustrated PDF manual walks through each tool.</p>${links}<ol class="pro-help-list"><li><b>Start a song.</b> Choose a starter on Play, or use New Song. Choose a meter and tempo, then open Chords to edit the arrangement.</li><li><b>Add words and chords.</b> Select a measure, choose its chord changes, and add a lyric phrase. Set when the phrase starts, its length, and any pickup.</li><li><b>Write a melody.</b> In Melody, choose a note length and Add notes. Tap a staff pitch or a letter button; notes go in order. Edit notes selects an existing note for pitch, length, and syllable changes. Use + / - to zoom.</li><li><b>Keep the song together.</b> In supported band meters, chord edits stay linked between Chords and Melody, the presentation, and newly generated exports. Use score &amp; present applies melody timing and opens the classroom stage. Older downloaded PDFs and videos need to be exported again.</li><li><b>Play for the class.</b> Play opens the stage. More options controls Play once, Play twice, or Loop. Stage opens themes and the separate student display; keep sound and controls in the teacher window.</li><li><b>Make a PDF.</b> Practice sheet makes a take-home chord/lyric guide. Melody &gt; Preview / print score makes treble notation with syllables and chord symbols.</li><li><b>Make a video.</b> Video studio lets you set a title, credits, closing message, transition, and play-throughs. Preview it, then Export video. Fast MP4 render uses built-in sound; wait for Download video.</li><li><b>Save and back up.</b> Save song keeps a named copy in this browser. More options &gt; Import &amp; export &gt; Export current song saves an editable JSON backup. Save again after edits. Imported files appear in My songs.</li></ol><p class="modal-note"><b>Downloaded edition:</b> Unzip the whole folder, then open Open-Uke-Strum-Pro.html. The Help folder contains this manual. Browser storage and video encoding depend on your browser; see the manual for recovery steps.</p><p class="hint" style="margin-top:16px">Created by <strong>Drew Wichman</strong></p>`);
 };
 document.querySelector('.options-help').insertAdjacentHTML('beforeend',`<a class="pro-manual-link" href="${manual}" target="_blank" rel="noopener">PDF manual ↗</a>`);
}
